"""KROVOSTOK, second Friday. Original game dialogue; no lyrics reproduced.

Sources in the working catalogue:
SK02 'Сдавать говно' — errand to clinic, meeting Dimon; Dimon named in song.
RK06 'Теряю голову' — Olya, anxious admirer, cinema; Olya named in song.
LO11 'Снайпер' — aging professional, Bach and boundaries; unnamed in song.
All contacts, texting, inter-song relationships, concrete branches are game invention.
"""
import json
from pathlib import Path


def m(who, text, kind='in', **extra):
    return dict(who=who, text=text, kind=kind, **extra)


def f(source, destination, text):
    return m(destination, text, 'forward', **{'from': source, 'sent_by': 'me'})


def c(letter, title, echo, flag, value, reply, extra=None):
    return dict(id=letter, title=title, echo=echo, set={flag:value},
                lines=[m(*x) if isinstance(x,tuple) else x for x in reply]+(extra or []), note='')


def v(when, *messages):
    return dict(when=when,lines=[m(*x) if isinstance(x,tuple) else x for x in messages])


def s(n, time, heading, chat, lines, choices, variants=None):
    entry=dict(id=f'R{n:02}',title=f'Пятница, {time} — {heading}',chat=chat,
               core=[m(*x) if isinstance(x,tuple) else x for x in lines],choices=choices)
    if variants: entry['variants']=variants
    return entry

