assert len(scenes)==18
assert [x['id'] for x in scenes] == [f'R{i:02}' for i in range(1,19)]
assert all(len(x['choices'])==3 and len(x['core'])>=3 for x in scenes)

js="""/* Second Friday: original dialogue based on selected story motifs. */\n(function(){\n 'use strict';\n const s=window.KROVO_STORY;\n if(!s||!Array.isArray(s.scenes))throw Error('Load story.js and second_thursday.js before next_friday.js');\n if(s.scenes.some(x=>x.id==='R01'))return;\n const next="""+json.dumps(scenes,ensure_ascii=False,separators=(',',':'))+""";\n s.scenes.push(...next);\n s.meta.scenes=s.scenes.length;\n s.meta.title='КРОВОСТОК — Переписки / Вторая пятница';\n})();\n"""
Path(__file__).with_name('next_friday.js').write_text(js,encoding='utf-8')
print('Generated second Friday',len(scenes),'scenes',len(js),'chars')
